const input = $input.first().json;
const targetUrls = Array.isArray(input.board_tokens) && input.board_tokens.length > 0
  ? input.board_tokens
  : [
      'https://remotive.com/api/remote-jobs?category=devops',
      'https://weworkremotely.com/categories/remote-devops-sysadmin-jobs.rss'
    ];

const queries = Array.isArray(input.user_preferences?.target_job_titles) && input.user_preferences.target_job_titles.length > 0
  ? input.user_preferences.target_job_titles
  : ['DevOps Engineer', 'Platform Engineer'];

return targetUrls.map(url => ({
  json: {
    target_url: url,
    search_queries: queries,
    scrape_endpoint: ($env.DOCX_SERVICE_URL || 'http://docx-service:3001') + '/scrape',
    jsearch_enabled: Boolean($env.JSEARCH_RAPIDAPI_KEY)
  }
}));

const crypto = require('crypto');
const normalized = [];

for (const item of $input.all()) {
  const payload = item.json;
  if (!payload) continue;

  // 1. Handle jobs returned directly by POST /scrape
  if (Array.isArray(payload.jobs)) {
    for (const j of payload.jobs) {
      if (j && j.job_id && j.title) {
        normalized.push({ json: j });
      }
    }
  }

  // 2. Handle jobs returned by JSearch (LinkedIn / Indeed / Glassdoor / Naukri aggregator)
  if (Array.isArray(payload.data)) {
    for (const post of payload.data) {
      if (!post.job_id || !post.job_title) continue;
      const title = String(post.job_title).trim();
      const company = String(post.employer_name || 'Portal Employer').trim();
      const location = [post.job_city, post.job_state, post.job_country].filter(Boolean).join(', ') || 'Remote';
      const workMode = post.job_is_remote ? 'remote' : 'onsite';
      const desc = String(post.job_description || '').trim();
      const appUrl = String(post.job_apply_link || post.job_google_link || '').trim();
      const canonicalUrl = appUrl.split('?')[0].replace(/\/+$/, '');
      const fallbackHash = crypto
        .createHash('sha256')
        .update(`${company.toLowerCase()}|${title.toLowerCase()}|${location.toLowerCase()}`)
        .digest('hex');
      const descHash = crypto.createHash('sha256').update(desc).digest('hex');

      normalized.push({
        json: {
          job_id: `portal_${post.job_id}`,
          source: String(post.job_publisher || 'portal_search').toLowerCase().replace(/[^a-z0-9_]/g, '_'),
          title,
          company,
          location,
          work_mode: workMode,
          employment_type: String(post.job_employment_type || 'full-time').toLowerCase(),
          experience_required: null,
          required_skills: [],
          preferred_skills: [],
          job_description: desc,
          description_sha256: descHash,
          salary_range: post.job_min_salary ? `${post.job_min_salary}-${post.job_max_salary} ${post.job_salary_currency || 'USD'}` : null,
          posted_at: post.job_posted_at_datetime_utc || new Date().toISOString(),
          application_url: appUrl,
          canonical_url: canonicalUrl,
          fallback_dedup_hash: fallbackHash,
          status: 'discovered'
        }
      });
    }
  }
}

return normalized;
